-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

create table public.quiz_progress (
  user_id uuid default auth.uid() not null,
  quiz_id text not null,
  section_id text not null,
  preferences jsonb default '{}'::jsonb not null,
  round jsonb,
  updated_at timestamp with time zone default now() not null,
  constraint quiz_progress_pkey PRIMARY KEY (user_id, quiz_id, section_id),
  constraint quiz_progress_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE,
  constraint quiz_progress_preferences_check CHECK (((jsonb_typeof(preferences) = 'object'::text) AND (octet_length((preferences)::text) <= 20000))),
  constraint quiz_progress_quiz_id_check CHECK ((quiz_id ~ '^[a-z0-9]+(-[a-z0-9]+)*$'::text)),
  constraint quiz_progress_round_check CHECK (((round IS NULL) OR ((jsonb_typeof(round) = 'object'::text) AND (octet_length((round)::text) <= 1000000)))),
  constraint quiz_progress_section_id_check CHECK ((section_id ~ '^[a-z0-9]+(-[a-z0-9]+)*$'::text))
);

CREATE TRIGGER quota_quiz_bytes AFTER INSERT OR DELETE OR UPDATE ON public.quiz_progress FOR EACH ROW EXECUTE FUNCTION public.quota_quiz_bytes();
CREATE TRIGGER quota_rows AFTER INSERT ON public.quiz_progress FOR EACH ROW EXECUTE FUNCTION public.quota_rows('2000');

alter table public.quiz_progress enable row level security;

create policy "own quiz progress" on public.quiz_progress
  as permissive
  for all
  to authenticated
  using (((user_id = ( SELECT auth.uid() AS uid)) AND ( SELECT public.is_allowed_user() AS is_allowed_user)))
  with check (((user_id = ( SELECT auth.uid() AS uid)) AND ( SELECT public.is_allowed_user() AS is_allowed_user)));

grant delete, select on table public.quiz_progress to authenticated;
grant delete, insert, maintain, references, select, trigger, truncate, update on table public.quiz_progress to service_role;
